sp_AtualizarEstoqueMinimo	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_AtualizarEstoqueMinimo`(\n\n    p_produto_id  INT,\n\n    p_estoqueMin  INT\n\n)\nBEGIN\n\n    UPDATE Estoque\n\n    SET estoqueMin = p_estoqueMin,\n\n        dthAtualizacao = CURDATE()\n\n    WHERE produto_id = p_produto_id;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
